// getCertificate returns a cached certificate only while it has at least a minute
// of validity remaining. Serializing requests by identity avoids duplicate CSRs.
func (f *Forwarder) getCertificate(ctx authContext) (*tls.Config, error) {
	if cert := f.cachedCertificate(ctx); cert != nil {
		return cert, nil
	}
	for {
		requestCtx, cancel := f.getOrCreateRequestContext(ctx.key())
		if cancel != nil {
			defer cancel()
			if cert := f.cachedCertificate(ctx); cert != nil {
				return cert, nil
			}
			cert, err := f.requestCertificate(ctx)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			f.Lock()
			err = f.credentials.Set(ctx.key(), cert, ctx.sessionTTL)
			f.Unlock()
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return cert, nil
		}
		select {
		case <-requestCtx.Done():
		case <-f.ctx.Done():
			return nil, trace.BadParameter("forwarder is closing, aborting the request")
		}
	}
}

func (f *Forwarder) cachedCertificate(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	cert, ok := f.credentials.Get(ctx.key())
	if !ok {
		return nil
	}
	config := cert.(*tls.Config)
	if len(config.Certificates) == 0 || config.Certificates[0].Leaf == nil ||
		config.Certificates[0].Leaf.NotAfter.Before(f.Clock.Now().Add(time.Minute)) {
		f.credentials.Remove(ctx.key())
		return nil
	}
	return config
}
